package com.fakelegacy.order.pricing;

import java.util.ArrayList;
import java.util.List;

import org.springframework.stereotype.Component;

@Component
public class PriceCalculator {

    private final List<AbstractDiscountStep> steps = new ArrayList<>();

    public PriceCalculator() {
        // order matters: the volume discount works on the amount left after the tier discount
        steps.add(new TierDiscountStep());
        steps.add(new VolumeDiscountStep());
    }

    /** Applies tier and volume discounts; promo discounts are set by the caller before close(). */
    public PricingResult calculate(List<LineDraft> lines, String tier) {
        for (LineDraft line : lines) {
            for (AbstractDiscountStep step : steps) {
                step.apply(line, tier);
            }
        }
        return new PricingResult(lines);
    }

    /** Computes line and goods totals; DiscountCapAspect post-processes the result. */
    public PricingResult close(PricingResult result) {
        result.recomputeTotals();
        return result;
    }
}
